/**
 * The server-side key of the test-data masking (`mask` argument). Generated by this server
 * on first use and kept next to the active profile, readable by the owner only:
 *   ${SC4SAP_HOME_DIR | ~/.sc4sap}/profiles/<alias>/mask.key   (legacy, no alias: …/mask.key)
 * POSIX: file mode 600. Windows: the mode bits are not applied, so the file's ACL is set to the
 * owner alone (inheritance removed) with icacls — on creation and once per process for a key
 * created earlier.
 * It never appears in a tool argument, a response, a log line or the plugin: the model
 * knows only the run salt, which is a namespace, not a key. So tokens cannot be recomputed
 * from a guessed value (dictionary) without this file. The same OS user can still read it
 * (residual risk accepted for local, single-user use).
 */
import { execFileSync } from 'node:child_process';
import { randomBytes } from 'node:crypto';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { getActiveAlias } from '../profile';

const KEY_HEX = /^[0-9a-f]{64}$/;
const hardened = new Set<string>();

export function maskSecretPath(): string {
  const home =
    process.env.SC4SAP_HOME_DIR || path.join(os.homedir(), '.sc4sap');
  const alias = getActiveAlias();
  return alias
    ? path.join(home, 'profiles', alias, 'mask.key')
    : path.join(home, 'mask.key');
}

/** The Windows account icacls should grant: DOMAIN\user when the domain is known. */
export function windowsAccount(
  env: NodeJS.ProcessEnv = process.env,
  user: string = os.userInfo().username,
): string {
  return env.USERDOMAIN ? `${env.USERDOMAIN}\\${user}` : user;
}

/**
 * Owner-only access on Windows: `icacls <file> /inheritance:r /grant:r <user>:F` removes the
 * inherited entries (SYSTEM, Administrators, …) and leaves the owner. No-op elsewhere (mode 600
 * is set at creation). A failure throws: the key is not used unprotected.
 */
export function hardenKeyFile(
  file: string,
  platform: NodeJS.Platform = process.platform,
  exec: typeof execFileSync = execFileSync,
  account: string = platform === 'win32' ? windowsAccount() : '',
): void {
  if (platform !== 'win32') return;
  const fail = (why: string) =>
    new Error(
      `mask: the masking key could not be restricted to its owner (${why}); rows are not returned`,
    );
  let acl = '';
  try {
    // A new file can carry explicit entries (SYSTEM, Administrators): /reset turns them into
    // inherited ones, then /inheritance:r drops all inherited entries and /grant:r leaves the owner.
    exec('icacls', [file, '/reset'], { stdio: 'ignore', windowsHide: true });
    exec('icacls', [file, '/inheritance:r', '/grant:r', `${account}:F`], {
      stdio: 'ignore',
      windowsHide: true,
    });
    acl = String(
      exec('icacls', [file], { encoding: 'utf8', windowsHide: true }) ?? '',
    );
  } catch {
    throw fail('icacls did not run');
  }
  // Verify: exactly one entry left, the owner's.
  const entries = acl
    .split(/\r?\n/)
    .map((l) => l.replace(file, '').trim())
    .filter((l) => /:\(/.test(l));
  if (entries.length !== 1)
    throw fail(`${entries.length} access entries remain instead of 1`);
  if (!entries[0].toLowerCase().startsWith(`${account.toLowerCase()}:`))
    throw fail(
      `the remaining entry is not ${account} — on an Azure AD or Microsoft-account sign-in the owner name can differ from USERDOMAIN\\user`,
    );
}

function readKey(file: string): Buffer {
  const hex = fs.readFileSync(file, 'utf8').trim();
  if (!KEY_HEX.test(hex))
    throw new Error(
      'mask: the masking key file is not a 64-hex key; rows are not returned',
    );
  return Buffer.from(hex, 'hex');
}

function useKey(file: string): Buffer {
  if (!hardened.has(file)) {
    hardenKeyFile(file);
    hardened.add(file);
  }
  return readKey(file);
}

/** The masking key; created (random, 256 bit, owner-only) when the profile has none yet. */
export function loadMaskSecret(): Buffer {
  const file = maskSecretPath();
  if (fs.existsSync(file)) return useKey(file);
  fs.mkdirSync(path.dirname(file), { recursive: true });
  try {
    fs.writeFileSync(file, `${randomBytes(32).toString('hex')}\n`, {
      encoding: 'utf8',
      mode: 0o600,
      flag: 'wx',
    });
  } catch (e: any) {
    // Another process created it first: use that one.
    if (e?.code !== 'EEXIST')
      throw new Error(
        'mask: the masking key could not be created; rows are not returned',
      );
  }
  return useKey(file);
}

/** Tests only: forget which key files were restricted in this process. */
export function resetHardenedForTests(): void {
  hardened.clear();
}
